import{_ as t,o as i,c as n,a2 as s}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Loi sur la Garantie du Logement","description":"","frontmatter":{},"headers":[],"relativePath":"fr/45-住房保障法.md","filePath":"fr/45-住房保障法.md"}'),a={name:"fr/45-住房保障法.md"};function r(o,e,l,d,u,c){return i(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="loi-sur-la-garantie-du-logement" tabindex="-1">Loi sur la Garantie du Logement <a class="header-anchor" href="#loi-sur-la-garantie-du-logement" aria-label="Permalink to &quot;Loi sur la Garantie du Logement&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>45</td></tr><tr><td>Module</td><td>Système Juridique et Cadre de Gouvernance</td></tr><tr><td>Mots clés</td><td>Droit de résidence, Logement garanti, Principes juridiques spatiaux, Environnement habitable, Anti-spéculation</td></tr></tbody></table><h2 id="i-objectif-legislatif-et-principes-fondamentaux" tabindex="-1">I. Objectif Législatif et Principes Fondamentaux <a class="header-anchor" href="#i-objectif-legislatif-et-principes-fondamentaux" aria-label="Permalink to &quot;I. Objectif Législatif et Principes Fondamentaux&quot;">​</a></h2><p>La <em>Loi sur la Garantie du Logement</em> est l&#39;une des cinq lois d&#39;accompagnement de la Civilisation Symbiotique de l&#39;Ancre. Elle vise à garantir le droit de résidence de toutes les vies au sein de l&#39;Univers Hengyuan, à établir un système de garantie du logement équitable et durable, à utiliser la technologie de régulation des principes juridiques spatiaux pour fournir des espaces de vie adaptés aux Dix Mille Races, et à prévenir la spéculation et la prédation dans le secteur du logement.</p><p>Cette Loi établit les principes fondamentaux suivants :</p><table tabindex="0"><thead><tr><th>Principe</th><th>Contenu</th></tr></thead><tbody><tr><td>Garantie de résidence</td><td>Chaque vie a le droit d&#39;obtenir un espace de vie adapté ; l&#39;État et la civilisation ont l&#39;obligation de garantir les besoins fondamentaux de résidence</td></tr><tr><td>Priorité à l&#39;intérêt public</td><td>Le logement est d&#39;abord une nécessité de vie plutôt qu&#39;un bien spéculatif ; le logement garanti a un attribut d&#39;intérêt public</td></tr><tr><td>Efficacité spatiale</td><td>Utiliser la technologie de régulation des principes juridiques spatiaux pour améliorer l&#39;efficacité d&#39;utilisation de l&#39;espace et étendre l&#39;espace habitable</td></tr><tr><td>Adaptation aux autres races</td><td>Fournir des espaces de vie adaptés aux caractéristiques physiologiques et aux habitudes de vie des différentes races</td></tr><tr><td>Environnement habitable</td><td>Les espaces de vie doivent posséder un bon environnement écologique, des infrastructures et des services publics</td></tr><tr><td>Anti-spéculation</td><td>Interdire la spéculation sur le logement comme cible, empêchant le logement de devenir un outil de pillage des richesses</td></tr></tbody></table><h2 id="ii-garanties-juridiques-du-droit-de-residence" tabindex="-1">II. Garanties Juridiques du Droit de Résidence <a class="header-anchor" href="#ii-garanties-juridiques-du-droit-de-residence" aria-label="Permalink to &quot;II. Garanties Juridiques du Droit de Résidence&quot;">​</a></h2><p>Cette Loi stipule explicitement que le droit de résidence est un droit fondamental conféré à chaque vie par la Constitution Symbiotique, comprenant notamment :</p><ol><li><strong>Droit fondamental de résidence</strong> : chaque vie a le droit d&#39;obtenir un espace de vie non inférieur au niveau minimum, le niveau minimum étant déterminé selon la taille corporelle et les besoins de vie de chaque race.</li><li><strong>Droit de demander un logement garanti</strong> : les vies remplissant les conditions ont le droit de demander un logement garanti, avec des conditions de demande et des normes d&#39;attribution ouvertes et transparentes.</li><li><strong>Droit à la sécurité de résidence</strong> : les espaces de vie doivent répondre aux normes de sécurité ; les bâtiments dangereux et les espaces de vie inadaptés ne doivent pas être loués ou attribués.</li><li><strong>Droit à la stabilité de résidence</strong> : les résidents des logements garantis jouissent de droits de résidence stables lorsqu&#39;ils remplissent les conditions et ne doivent pas être expulsés arbitrairement.</li><li><strong>Droit à l&#39;environnement de vie</strong> : les résidents ont le droit d&#39;obtenir un air pur, des sources d&#39;eau et un bon environnement environnant, et le droit de déposer des plaintes contre la pollution environnementale.</li><li><strong>Droit à la rénovation du logement</strong> : les résidents ont le droit de rénover raisonnablement leur espace de vie à condition de ne pas affecter la sécurité du bâtiment et les droits d&#39;autrui.</li></ol><h2 id="iii-systeme-de-garantie-du-logement" tabindex="-1">III. Système de Garantie du Logement <a class="header-anchor" href="#iii-systeme-de-garantie-du-logement" aria-label="Permalink to &quot;III. Système de Garantie du Logement&quot;">​</a></h2><p>Le système de garantie du logement de la Civilisation Symbiotique de l&#39;Ancre est divisé en trois types de logements, couvrant différents niveaux de besoins :</p><table tabindex="0"><thead><tr><th>Type</th><th>Nom</th><th>Groupe garanti</th><th>Méthode d&#39;attribution</th><th>Loyer/Prix</th></tr></thead><tbody><tr><td>Premier type</td><td>Logement locatif public</td><td>Groupes à faibles revenus, cultivateurs débutants, nouveaux immigrants</td><td>Système de demande et de vérification, attribution par file d&#39;attente</td><td>Loyer faible symbolique</td></tr><tr><td>Deuxième type</td><td>Logement en propriété partagée</td><td>Groupes à revenus moyens, cultivateurs intermédiaires</td><td>Système de demande et de vérification, attribution par tirage au sort</td><td>Sous le prix du marché, propriété partagée entre l&#39;individu et l&#39;État</td></tr><tr><td>Troisième type</td><td>Logement commercial</td><td>Groupes à revenus élevés, cultivateurs avancés</td><td>Transaction de marché</td><td>Prix du marché, soumis à régulation</td></tr></tbody></table><p>En outre, la technologie de régulation des principes juridiques spatiaux est utilisée pour construire des « zones résidentielles à espace plié » : élargir la superficie résidentielle dans un espace physique limité par la technologie de pliage spatial, fournissant plus d&#39;espace de vie aux zones à haute densité. Les zones résidentielles à espace plié doivent subir une évaluation de sécurité pour garantir la stabilité spatiale.</p><h2 id="iv-adaptation-du-logement-pour-les-autres-races" tabindex="-1">IV. Adaptation du Logement pour les Autres Races <a class="header-anchor" href="#iv-adaptation-du-logement-pour-les-autres-races" aria-label="Permalink to &quot;IV. Adaptation du Logement pour les Autres Races&quot;">​</a></h2><p>En réponse aux besoins spéciaux de résidence des différentes races au sein de l&#39;Univers Hengyuan, cette Loi établit une institution d&#39;adaptation du logement pour les autres races :</p><ul><li><strong>Races aquatiques</strong> : fourniture d&#39;espaces de vie sous-marins ou de résidences amphibies, équipés de systèmes de circulation d&#39;eau et de maintien de la qualité de l&#39;eau.</li><li><strong>Races volantes</strong> : fourniture d&#39;espaces de vie en haute altitude ou de résidences avec plateformes de décollage et d&#39;atterrissage, équipés de gestion du trafic aérien.</li><li><strong>Vies énergétiques</strong> : fourniture d&#39;espaces de vie à concentration énergétique adaptée, équipés de dispositifs de stabilisation énergétique.</li><li><strong>Races géantes</strong> : fourniture d&#39;espaces de vie à grande échelle, avec structures de bâtiment spécialement renforcées.</li><li><strong>Races microscopiques</strong> : fourniture de zones résidentielles microscopiques, équipées de passages à échelle et d&#39;installations dédiées.</li></ul><p>Les normes d&#39;adaptation du logement pour les autres races sont élaborées conjointement par l&#39;autorité compétente du logement et les représentants des différentes races, et mises à jour régulièrement.</p><h2 id="v-construction-et-gestion-du-logement" tabindex="-1">V. Construction et Gestion du Logement <a class="header-anchor" href="#v-construction-et-gestion-du-logement" aria-label="Permalink to &quot;V. Construction et Gestion du Logement&quot;">​</a></h2><ul><li><strong>Planification de la construction du logement</strong> : l&#39;État élabore des plans de construction du logement en fonction de la croissance démographique et de l&#39;immigration, assurant l&#39;équilibre entre l&#39;offre et la demande de logements.</li><li><strong>Normes de construction</strong> : la construction des logements garantis doit répondre aux normes de sécurité, de protection de l&#39;environnement et d&#39;habitabilité ; la baisse de la qualité de construction est interdite.</li><li><strong>Gestion immobilière</strong> : les zones résidentielles mettent en œuvre un modèle combinant gestion autonome et services immobiliers professionnels ; les résidents ont le droit de participer aux décisions de gestion immobilière.</li><li><strong>Entretien du logement</strong> : l&#39;entretien des logements garantis relève de l&#39;institution de gestion du logement, les fonds d&#39;entretien étant prélevés sur l&#39;accumulation publique.</li><li><strong>Mécanisme de sortie</strong> : les résidents des logements garantis dont les revenus ou la culture dépassent le niveau de garantie doivent sortir du logement garanti ou passer au logement commercial, avec une période de transition raisonnable accordée pour la sortie.</li></ul><h2 id="vi-anti-speculation-et-supervision" tabindex="-1">VI. Anti-Spéculation et Supervision <a class="header-anchor" href="#vi-anti-speculation-et-supervision" aria-label="Permalink to &quot;VI. Anti-Spéculation et Supervision&quot;">​</a></h2><p>Pour prévenir la spéculation et la prédation dans le secteur du logement, cette Loi établit les mesures de supervision suivantes :</p><ol><li>Limiter le nombre de logements commerciaux détenus par les individus ; des impôts fonciers progressifs sont prélevés sur les montants dépassant la limite.</li><li>Interdire la sous-location et la revente des logements garantis ; les contrevenants voient leur éligibilité à la garantie révoquée et leur logement récupéré.</li><li>Établir un système d&#39;information publique sur les transactions de logement, empêchant les opérations en coulisse et la manipulation des prix.</li><li>Mettre en œuvre une gestion des qualifications et une supervision des fonds pour les promoteurs immobiliers, empêchant les projets inachevés et la fraude.</li><li>Établir des mécanismes de plainte et de règlement des litiges relatifs au logement, protégeant les droits et intérêts légitimes des résidents.</li></ol><h2 id="vii-responsabilite-juridique" tabindex="-1">VII. Responsabilité Juridique <a class="header-anchor" href="#vii-responsabilite-juridique" aria-label="Permalink to &quot;VII. Responsabilité Juridique&quot;">​</a></h2><p>Les actes violant les dispositions de cette Loi supportent les responsabilités suivantes selon la gravité des circonstances :</p><ul><li>Ceux qui attribuent des logements garantis en violation des règlements sont ordonnés de corriger et les personnes responsables sont sanctionnées.</li><li>Ceux qui sous-louent ou revendent des logements garantis voient leur éligibilité à la garantie révoquée, leur logement récupéré et sont amendés.</li><li>Les promoteurs qui baissent la qualité de construction sont ordonnés de refaire les travaux et amendés ; dans les cas graves, leurs qualifications sont révoquées.</li><li>Ceux qui se livrent à la spéculation sur le logement sont soumis à des taxes de spéculation élevées et à des amendes.</li><li>Ceux qui louent des bâtiments dangereux causant un préjudice aux résidents supportent la responsabilité d&#39;indemnisation ; dans les cas graves, la responsabilité pénale est poursuivie.</li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>La <em>Loi sur la Garantie du Logement</em> est la mise en œuvre de la philosophie « un chemin pour chacun » de la Civilisation Symbiotique de l&#39;Ancre dans le domaine de la résidence. En établissant un système de garantie du logement classifié, en utilisant la technologie des principes juridiques spatiaux pour étendre l&#39;espace de vie, en adaptant les besoins de résidence des autres races et en combattant la spéculation sur le logement, elle garantit que chaque vie puisse avoir un foyer sûr, adapté et stable, fournissant des garanties de résidence pour la progression commune des Dix Mille Races.</p><h2 id="documents-connexes" tabindex="-1">Documents Connexes <a class="header-anchor" href="#documents-connexes" aria-label="Permalink to &quot;Documents Connexes&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Constitution Symbiotique : Principes Généraux)</li><li>39-住房与环境保障 (Logement et Protection de l&#39;Environnement)</li><li>13-空间法理调度体系详解 (Explication Détaillée du Système de Régulation des Principes Juridiques Spatiaux)</li><li>46-环境保护法 (Loi sur la Protection de l&#39;Environnement)</li></ul>',29)])])}const g=t(a,[["render",r]]);export{m as __pageData,g as default};
